From 291b93ca2c50c8d4b712b92da30182f00193c174 Mon Sep 17 00:00:00 2001
From: Fengguang Wu <fengguang.wu@intel.com>
Date: Mon, 26 Mar 2018 21:41:30 +0200
Subject: [PATCH] staging: wilc1000: fix memdup.cocci warnings

drivers/staging/wilc1000/host_interface.c:946:32-39: WARNING opportunity for kmemdup
drivers/staging/wilc1000/host_interface.c:970:30-37: WARNING opportunity for kmemdup

 Use kmemdup rather than duplicating its implementation

Generated by: scripts/coccinelle/api/memdup.cocci

Fixes: aaea2164bdff ("staging: wilc1000: check for kmalloc allocation failures")
CC: Colin Ian King <colin.king@canonical.com>
Signed-off-by: Fengguang Wu <fengguang.wu@intel.com>
Signed-off-by: Julia Lawall <julia.lawall@lip6.fr>
Reviewed-by: Claudiu Beznea <claudiu.beznea@microchip.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

diff --git a/drivers/staging/wilc1000/host_interface.c b/drivers/staging/wilc1000/host_interface.c
index 1b32e717099b..6b5300ca44a6 100644
--- a/drivers/staging/wilc1000/host_interface.c
+++ b/drivers/staging/wilc1000/host_interface.c
@@ -936,12 +936,12 @@ static s32 handle_connect(struct wilc_vif *vif,
 	}

 	if (conn_attr->bssid) {
-		hif_drv->usr_conn_req.bssid = kmalloc(6, GFP_KERNEL);
+		hif_drv->usr_conn_req.bssid = kmemdup(conn_attr->bssid, 6,
+						      GFP_KERNEL);
 		if (!hif_drv->usr_conn_req.bssid) {
 			result = -ENOMEM;
 			goto error;
 		}
-		memcpy(hif_drv->usr_conn_req.bssid, conn_attr->bssid, 6);
 	}

 	hif_drv->usr_conn_req.ssid_len = conn_attr->ssid_len;
@@ -960,15 +960,13 @@ static s32 handle_connect(struct wilc_vif *vif,

 	hif_drv->usr_conn_req.ies_len = conn_attr->ies_len;
 	if (conn_attr->ies) {
-		hif_drv->usr_conn_req.ies = kmalloc(conn_attr->ies_len,
+		hif_drv->usr_conn_req.ies = kmemdup(conn_attr->ies,
+						    conn_attr->ies_len,
 						    GFP_KERNEL);
 		if (!hif_drv->usr_conn_req.ies) {
 			result = -ENOMEM;
 			goto error;
 		}
-		memcpy(hif_drv->usr_conn_req.ies,
-		       conn_attr->ies,
-		       conn_attr->ies_len);
 	}

 	hif_drv->usr_conn_req.security = conn_attr->security;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug stems from the manual memory allocation and copying process using `kmalloc` followed by `memcpy`, which can lead to potential errors such as memory allocation failures or incorrect memory handling. This pattern increases the risk of memory leaks or buffer overflows if not handled correctly. The use of `kmemdup` simplifies this process by combining allocation and copying, thus reducing the likelihood of such bugs.

        Commit message:
        staging: wilc1000: fix memdup.cocci warnings

drivers/staging/wilc1000/host_interface.c:946:32-39: WARNING opportunity for kmemdup
drivers/staging/wilc1000/host_interface.c:970:30-37: WARNING opportunity for kmemdup

 Use kmemdup rather than duplicating its implementation

Generated by: scripts/coccinelle/api/memdup.cocci

Fixes: aaea2164bdff ("staging: wilc1000: check for kmalloc allocation failures")
CC: Colin Ian King <colin.king@canonical.com>
Signed-off-by: Fengguang Wu <fengguang.wu@intel.com>
Signed-off-by: Julia Lawall <julia.lawall@lip6.fr>
Reviewed-by: Claudiu Beznea <claudiu.beznea@microchip.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>  

        Patch:
         u8 wilc_connected_ssid[6] = {0};
 static s32 handle_connect(struct wilc_vif *vif,
 			  struct connect_attr *conn_attr)
 {
 	s32 result = 0;
 	struct wid wid_list[8];
 	u32 wid_cnt = 0, dummyval = 0;
 	u8 *cur_byte = NULL;
 	struct join_bss_param *bss_param;
 	struct host_if_drv *hif_drv = vif->hif_drv;

 	if (memcmp(conn_attr->bssid, wilc_connected_ssid, ETH_ALEN) == 0) {
 		result = 0;
 		netdev_err(vif->ndev, "Discard connect request\n");
 		return result;
 	}

 	bss_param = conn_attr->params;
 	if (!bss_param) {
 		netdev_err(vif->ndev, "Required BSSID not found\n");
 		result = -ENOENT;
 		goto error;
 	}

 	if (conn_attr->bssid) {
-		hif_drv->usr_conn_req.bssid = kmalloc(6, GFP_KERNEL);
+		hif_drv->usr_conn_req.bssid = kmemdup(conn_attr->bssid, 6,
+						      GFP_KERNEL);
 		if (!hif_drv->usr_conn_req.bssid) {
 			result = -ENOMEM;
 			goto error;
 		}
-		memcpy(hif_drv->usr_conn_req.bssid, conn_attr->bssid, 6);
 	}

 	hif_drv->usr_conn_req.ssid_len = conn_attr->ssid_len;
 	if (conn_attr->ssid) {
 		hif_drv->usr_conn_req.ssid = kmalloc(conn_attr->ssid_len + 1,
 						     GFP_KERNEL);
 		if (!hif_drv->usr_conn_req.ssid) {
 			result = -ENOMEM;
 			goto error;
 		}
 		memcpy(hif_drv->usr_conn_req.ssid,
 		       conn_attr->ssid,
 		       conn_attr->ssid_len);
 		hif_drv->usr_conn_req.ssid[conn_attr->ssid_len] = '\0';
 	}

 	hif_drv->usr_conn_req.ies_len = conn_attr->ies_len;
 	if (conn_attr->ies) {
-		hif_drv->usr_conn_req.ies = kmalloc(conn_attr->ies_len,
+		hif_drv->usr_conn_req.ies = kmemdup(conn_attr->ies,
+						    conn_attr->ies_len,
 						    GFP_KERNEL);
 		if (!hif_drv->usr_conn_req.ies) {
 			result = -ENOMEM;
 			goto error;
 		}
-		memcpy(hif_drv->usr_conn_req.ies,
-		       conn_attr->ies,
-		       conn_attr->ies_len);
 	}

 	hif_drv->usr_conn_req.security = conn_attr->security;
 	hif_drv->usr_conn_req.auth_type = conn_attr->auth_type;
 	hif_drv->usr_conn_req.conn_result = conn_attr->result;
 	hif_drv->usr_conn_req.arg = conn_attr->arg;

 	wid_list[wid_cnt].id = WID_SUCCESS_FRAME_COUNT;
 	wid_list[wid_cnt].type = WID_INT;
 	wid_list[wid_cnt].size = sizeof(u32);
 	wid_list[wid_cnt].val = (s8 *)(&(dummyval));
 	wid_cnt++;

 	wid_list[wid_cnt].id = WID_RECEIVED_FRAGMENT_COUNT;
 	wid_list[wid_cnt].type = WID_INT;
 	wid_list[wid_cnt].size = sizeof(u32);
 	wid_list[wid_cnt].val = (s8 *)(&(dummyval));
 	wid_cnt++;

 	wid_list[wid_cnt].id = WID_FAILED_COUNT;
 	wid_list[wid_cnt].type = WID_INT;
 	wid_list[wid_cnt].size = sizeof(u32);
 	wid_list[wid_cnt].val = (s8 *)(&(dummyval));
 	wid_cnt++;

 	wid_list[wid_cnt].id = WID_INFO_ELEMENT_ASSOCIATE;
 	wid_list[wid_cnt].type = WID_BIN_DATA;
 	wid_list[wid_cnt].val = hif_drv->usr_conn_req.ies;
 	wid_list[wid_cnt].size = hif_drv->usr_conn_req.ies_len;
 	wid_cnt++;

 	wid_list[wid_cnt].id = (u16)WID_11I_MODE;
 	wid_list[wid_cnt].type = WID_CHAR;
 	wid_list[wid_cnt].size = sizeof(char);
 	wid_list[wid_cnt].val = (s8 *)&hif_drv->usr_conn_req.security;
 	wid_cnt++;

 	wid_list[wid_cnt].id = (u16)WID_AUTH_TYPE;
 	wid_list[wid_cnt].type = WID_CHAR;
 	wid_list[wid_cnt].size = sizeof(char);
 	wid_list[wid_cnt].val = (s8 *)&hif_drv->usr_conn_req.auth_type;
 	wid_cnt++;

 	wid_list[wid_cnt].id = (u16)WID_JOIN_REQ_EXTENDED;
 	wid_list[wid_cnt].type = WID_STR;
 	wid_list[wid_cnt].size = 112;
 	wid_list[wid_cnt].val = kmalloc(wid_list[wid_cnt].size, GFP_KERNEL);

 	if (!wid_list[wid_cnt].val) {
 		result = -EFAULT;
 		goto error;
 	}

 	cur_byte = wid_list[wid_cnt].val;

 	if (conn_attr->ssid) {
 		memcpy(cur_byte, conn_attr->ssid, conn_attr->ssid_len);
 		cur_byte[conn_attr->ssid_len] = '\0';
 	}
 	cur_byte += MAX_SSID_LEN;
 	*(cur_byte++) = INFRASTRUCTURE;

 	if (conn_attr->ch >= 1 && conn_attr->ch <= 14) {
 		*(cur_byte++) = conn_attr->ch;
 	} else {
 		netdev_err(vif->ndev, "Channel out of range\n");
 		*(cur_byte++) = 0xFF;
 	}
 	*(cur_byte++)  = (bss_param->cap_info) & 0xFF;
 	*(cur_byte++)  = ((bss_param->cap_info) >> 8) & 0xFF;

 	if (conn_attr->bssid)
 		memcpy(cur_byte, conn_attr->bssid, 6);
 	cur_byte += 6;

 	if (conn_attr->bssid)
 		memcpy(cur_byte, conn_attr->bssid, 6);
 	cur_byte += 6;

 	*(cur_byte++)  = (bss_param->beacon_period) & 0xFF;
 	*(cur_byte++)  = ((bss_param->beacon_period) >> 8) & 0xFF;
 	*(cur_byte++)  =  bss_param->dtim_period;

 	memcpy(cur_byte, bss_param->supp_rates, MAX_RATES_SUPPORTED + 1);
 	cur_byte += (MAX_RATES_SUPPORTED + 1);

 	*(cur_byte++)  =  bss_param->wmm_cap;
 	*(cur_byte++)  = bss_param->uapsd_cap;

 	*(cur_byte++)  = bss_param->ht_capable;
 	hif_drv->usr_conn_req.ht_capable = bss_param->ht_capable;

 	*(cur_byte++)  =  bss_param->rsn_found;
 	*(cur_byte++)  =  bss_param->rsn_grp_policy;
 	*(cur_byte++) =  bss_param->mode_802_11i;

 	memcpy(cur_byte, bss_param->rsn_pcip_policy,
 	       sizeof(bss_param->rsn_pcip_policy));
 	cur_byte += sizeof(bss_param->rsn_pcip_policy);

 	memcpy(cur_byte, bss_param->rsn_auth_policy,
 	       sizeof(bss_param->rsn_auth_policy));
 	cur_byte += sizeof(bss_param->rsn_auth_policy);

 	memcpy(cur_byte, bss_param->rsn_cap, sizeof(bss_param->rsn_cap));
 	cur_byte += sizeof(bss_param->rsn_cap);

 	*(cur_byte++) = REAL_JOIN_REQ;
 	*(cur_byte++) = bss_param->noa_enabled;

 	if (bss_param->noa_enabled) {
 		*(cur_byte++) = (bss_param->tsf) & 0xFF;
 		*(cur_byte++) = ((bss_param->tsf) >> 8) & 0xFF;
 		*(cur_byte++) = ((bss_param->tsf) >> 16) & 0xFF;
 		*(cur_byte++) = ((bss_param->tsf) >> 24) & 0xFF;

 		*(cur_byte++) = bss_param->opp_enabled;
 		*(cur_byte++) = bss_param->idx;

 		if (bss_param->opp_enabled)
 			*(cur_byte++) = bss_param->ct_window;

 		*(cur_byte++) = bss_param->cnt;

 		memcpy(cur_byte, bss_param->duration,
 		       sizeof(bss_param->duration));
 		cur_byte += sizeof(bss_param->duration);

 		memcpy(cur_byte, bss_param->interval,
 		       sizeof(bss_param->interval));
 		cur_byte += sizeof(bss_param->interval);

 		memcpy(cur_byte, bss_param->start_time,
 		       sizeof(bss_param->start_time));
 		cur_byte += sizeof(bss_param->start_time);
 	}

 	cur_byte = wid_list[wid_cnt].val;
 	wid_cnt++;

 	if (conn_attr->bssid)
 		memcpy(wilc_connected_ssid,
 		       conn_attr->bssid, ETH_ALEN);

 	result = wilc_send_config_pkt(vif, SET_CFG, wid_list,
 				      wid_cnt,
 				      wilc_get_vif_idx(vif));
 	if (result) {
 		netdev_err(vif->ndev, "failed to send config packet\n");
 		result = -EFAULT;
 		goto error;
 	} else {
 		hif_drv->hif_state = HOST_IF_WAITING_CONN_RESP;
 	}

 error:
 	if (result) {
 		struct connect_info conn_info;

 		del_timer(&hif_drv->connect_timer);

 		memset(&conn_info, 0, sizeof(struct connect_info));

 		if (conn_attr->result) {
 			if (conn_attr->bssid)
 				memcpy(conn_info.bssid, conn_attr->bssid, 6);

 			if (conn_attr->ies) {
 				conn_info.req_ies_len = conn_attr->ies_len;
 				conn_info.req_ies = kmalloc(conn_attr->ies_len,
 							    GFP_KERNEL);
 				memcpy(conn_info.req_ies,
 				       conn_attr->ies,
 				       conn_attr->ies_len);
 			}

 			conn_attr->result(CONN_DISCONN_EVENT_CONN_RESP,
 							       &conn_info,
 							       MAC_DISCONNECTED,
 							       NULL,
 							       conn_attr->arg);
 			hif_drv->hif_state = HOST_IF_IDLE;
 			kfree(conn_info.req_ies);
 			conn_info.req_ies = NULL;

 		} else {
 			netdev_err(vif->ndev, "Connect callback is NULL\n");
 		}
 	}

 	kfree(conn_attr->bssid);
 	conn_attr->bssid = NULL;

 	kfree(conn_attr->ssid);
 	conn_attr->ssid = NULL;

 	kfree(conn_attr->ies);
 	conn_attr->ies = NULL;

 	kfree(cur_byte);
 	return result;
 }



